package com.company.tpm.certification;import java.time.*;import org.junit.jupiter.api.*;class CertificationStatusServiceTest{@Test void detectsExpiry(){var s=new CertificationStatusService();var today=LocalDate.of(2026,8,30);Assertions.assertEquals(CertificationStatusService.Status.EXPIRED,s.status(today.minusDays(1),today,30));Assertions.assertEquals(CertificationStatusService.Status.EXPIRING_SOON,s.status(today.plusDays(7),today,30));}}
